  // The how-to-play read (HowToPlayDialog.tsx). The dialog's title and the
  // composer-mode pills reuse home.howToPlay and table.composer.mode.*.
  // Pieces a highlight splits are _before/_after pairs around the lit span.
  "help.howToPlay.what.title": "What this is",
  "help.howToPlay.what.p1": "Open Game Master is a Dungeons & Dragons 5e table where an AI sits in the Dungeon Master's chair, or a friend does with the AI as their assistant. You and your friends play the adventurers. The app is the rulebook and the dice.",
  "help.howToPlay.what.p2": "Every table runs on the 5e rules. Where it is set is up to you: a genre of your choosing, or one of the pre-built worlds your server has installed.",
  "help.howToPlay.started.title": "Getting started",
  "help.howToPlay.started.p1Span": "New campaign",
  "help.howToPlay.started.p1After": " creates the world: pick a genre, difficulty and starting level, and optionally give the GM a secret story setup only it will know. If the server has campaign plugins installed, you can pick a pre-built world here instead of a bare genre, which brings its own races, classes, monsters and lore without changing a rule. You get an eight-letter invite code to share with your friends.",
  "help.howToPlay.started.p2Span": "Solo adventure",
  "help.howToPlay.started.p2Mid": " is the same thing for one player. To join someone else's table, paste their code into “",
  "help.howToPlay.started.p2Tail": "” or open the invite link they send you.",
  "help.howToPlay.started.p3": "Then build a character in the creation wizard, or reuse one saved under Characters in the account menu. Everyone readies up in the lobby, and the campaign owner starts the adventure.",
  "help.howToPlay.run.title": "How the game is run",
  "help.howToPlay.run.p1": "The app does all the calculation and gives the result to the GM, who weaves it into the story. Attack rolls, damage, saving throws, death saves, conditions, spell slots, rests, XP and level-ups are all resolved by the server against the 5e rules and written straight to your character sheet.",
  "help.howToPlay.run.p2": "The GM narrates what those results mean. It cannot invent a roll or quietly hand you a bonus, so play the story rather than arguing the numbers. Every roll and stat change is recorded in the Log, under the Story tab, if you want to check the maths.",
  "help.howToPlay.turn.title": "Taking your turn",
  "help.howToPlay.turn.intro": "The buttons above the message box change what your message means:",
  "help.howToPlay.turn.do": "Describe what your character does. The GM narrates the outcome and asks for a roll when the rules call for one.",
  "help.howToPlay.turn.say": "Speak in character. Your text is sent as spoken dialogue.",
  "help.howToPlay.turn.ooc": "Out-of-character table talk. The GM does not read it or respond to it.",
  "help.howToPlay.turn.askBefore": "To ask the GM a question about the story, the world, the rules, or your sheet, open the ",
  "help.howToPlay.turn.askAfter": " strip just above the message box. The answer quotes what the campaign has on record, and you choose whether it is just for you or for the whole table. Asking never moves the story on, so it works even while the floor is locked.",
  "help.howToPlay.wait.title": "One turn at a time",
  "help.howToPlay.wait.p1": "When the GM starts thinking, it reads everything sent up to that moment and writes one reply for the whole table. Anything you send while it is still thinking will not change that reply. It is picked up on the next turn, together with whatever everyone else sent.",
  "help.howToPlay.wait.p2Before": "So if you are playing with others, ",
  "help.howToPlay.wait.p2Span": "talk your options over before someone sends, then send one clear action each",
  "help.howToPlay.wait.p2After": ". Piling on more messages mid-narration does not speed the GM up or steer the reply already in progress.",
  "help.howToPlay.wait.p3": "OOC is the safe channel for that discussion: it never wakes the GM, and it still works while the floor is locked during narration. Sometimes the GM puts one player in the spotlight and waits for them, and a banner will tell you when that is why you cannot act.",
  "help.howToPlay.re.title": "If a reply lands badly",
  "help.howToPlay.re.p1Before": "Nothing the GM writes is final. Hovering one of its messages shows a row of actions. The party lead can have it ",
  "help.howToPlay.re.reroll": "reroll",
  "help.howToPlay.re.p1Mid": " that moment, with the same dice and the same outcome and only the wording changed, then page between the takes and leave the best one up for the table. The lead can also have it ",
  "help.howToPlay.re.continue": "continue",
  "help.howToPlay.re.p1After": " a reply that stopped short, or edit the wording by hand.",
  "help.howToPlay.re.p2": "Two of those actions are open to everyone. Anyone can check a passage against what the campaign has already established, and anyone can select a line and press the pin to keep that detail in front of the GM for the rest of the campaign.",
  "help.howToPlay.stuck.title": "If you get stuck",
  "help.howToPlay.stuck.p1": "The Help entry, in the account menu here and in the header during a session, walks through every button and panel: the side panel tabs, the Ask strip, the per-message actions, dice options, narration voice, notes, whispers, world packs and the party lead's powers. If a spotlight leaves the table stuck, the party lead can release it.",
