  "admin.worlds.clearFilter": "Clear the filter",
  "admin.worlds.intro": "A world pack renames the rules into a setting: its own races, classes, spells, gear, monsters, factions and lore, plus a brief telling the GM how that world sounds. Every mechanic stays 5e, so a character built in one still works anywhere.",
  "admin.worlds.disclaimer": "Packs based on an existing universe are community works. They are not distributed with Open Game Master, are not covered by its MIT license, and are not endorsed by the rights holders of the settings they reference. Installing one is your decision as the operator of this server.",
