  "admin.builtin.whisperNoModel": "A Whisper service answers, but no model is picked for it and it doesn't list exactly one, so dictation skips it. Pick its model in the Whisper model field.",
  "admin.builtin.openaiNoModel": "An OpenAI key is saved, but no transcription model is picked, so nothing is heard until you pick one under OpenAI transcription in Admin > Speech.",
  "admin.speech.heading": "Speech",
  "admin.speech.narration": "Narration (text to speech)",
  "admin.speech.narrationIntro": "Reads each of the storyteller's passages aloud in campaigns that switch Narration on. Campaigns only choose a voice; where the text is sent is decided here, for all of them.",
