  "admin.storage.firstRun": "; the first runs at {time}",
  "admin.storage.tidyNow": "Tidy now",
  "admin.storage.compact": "Compact database",
  "admin.storage.compactConfirm": "Compact the database? It is rewritten without its free space, and play pauses while that runs: a second or two for most servers. Afterwards the daily tidy hands freed space back by itself.",
  "admin.storage.compactTitle": "Compact the database?",
  "admin.storage.compactAction": "Compact",
