  "table.settings.dice.tip": "Real dice lets each player opt in to rolling at their table: the game parks until they type the result, read it from a paired Pixels Bluetooth die, or let the server roll per die (Dice sources, in the Party tab).",
  "table.settings.dice.policy": "Dice policy",
  "table.settings.hp.tip": "How hit points grow after 1st level (1st is always the hit die's highest face plus Constitution). Rolled dice are thrown by the server.",
