  "table.settings.narration.off": "Off",
  "table.settings.narration.offServer": "Off on this server",
  "table.settings.narration.voice": "Narration voice",
  "table.settings.narration.note": "Whether the story is read aloud is the whole table's setting. How loud it plays, or muting it, is each person's own, from the speaker button at the table.",
  "table.settings.theatre.tip": "Theatre inserts: when a passage has someone speaking, their portrait comes up over the scene art while their lines play.",
  "table.settings.theatre.on": "Theatre inserts on",
  "table.settings.theatre.off": "Theatre inserts off",
